import { test, expect } from '@playwright/test';

test.describe('Video Captions Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/videos');
  });

  test('should display captions when video is played', async ({ page }) => {
    // Locate and click the first video using getByRole
    const videoContainer = page.getByRole('region', { name: /video/i });
    await videoContainer.click();

    // Verify caption container is visible
    const captionContainer = page.getByRole('region', { name: /captions/i });
    await expect(captionContainer).toBeVisible();

    // Verify caption text is present
    const captionText = page.getByText(/caption text/i);
    await expect(captionText).toBeVisible();

    // Verify caption controls are accessible
    const captionControls = page.getByRole('button', { name: /close/i });
    await expect(captionControls).toBeVisible();

    // Verify caption controls are functional
    const captionClose = page.getByRole('button', { name: /close/i });
    await captionClose.click();
    await expect(captionContainer).not.toBeVisible();
  });

  test('should hide captions when video is paused or closed', async ({ page }) => {
    // Locate and click the first video using getByRole
    const videoContainer = page.getByRole('region', { name: /video/i });
    await videoContainer.click();

    // Verify caption container is visible
    const captionContainer = page.getByRole('region', { name: /captions/i });
    await expect(captionContainer).toBeVisible();

    // Verify caption text is present
    const captionText = page.getByText(/caption text/i);
    await expect(captionText).toBeVisible();

    // Verify caption controls are accessible
    const captionControls = page.getByRole('button', { name: /close/i });
    await expect(captionControls).toBeVisible();

    // Verify captions are hidden when video is paused
    const pauseButton = page.getByRole('button', { name: /pause/i });
    await pauseButton.click();
    await expect(captionContainer).not.toBeVisible();

    // Verify captions are hidden when video is closed
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();
    await expect(captionContainer).not.toBeVisible();
  });
});
